const api = game.modules.get("wang-pf2e-homebrew")?.api;
if (!api?.createMorrowEphemeraBook) {
  ui.notifications.error("wang-pf2e-homebrew API 不可用");
  return;
}
if (!game.modules.get("ephemera")?.active) {
  ui.notifications.error("请先启用 Ephemera");
  return;
}
ui.notifications.info("正在用 Ephemera 生成《莫罗医生的日记》…");
const entry = await api.createMorrowEphemeraBook({ open: true });
ui.notifications.info(`已创建：${entry.name}`);
